local function norm(x)return tostring(x or ''):lower():gsub('[^%w]','')end
local function mk(parent,n,size,col,cf,shape,mat)local x=Instance.new('Part')x.Name=n x.Size=size x.Color=col x.CFrame=cf or CFrame.new()x.Anchored=false x.CanCollide=false x.CanTouch=false x.CanQuery=false x.Massless=true x.TopSurface=Enum.SurfaceType.Smooth x.BottomSurface=Enum.SurfaceType.Smooth if shape then x.Shape=shape end x.Material=mat or Enum.Material.SmoothPlastic x.Parent=parent return x end
local function ball(p,n,s,c,cf,mat)return mk(p,n,s,c,cf,Enum.PartType.Ball,mat)end
local function cyl(p,n,s,c,cf,mat)return mk(p,n,s,c,cf,Enum.PartType.Cylinder,mat)end
local function parts(m)local t={}for _,d in ipairs(m:GetDescendants())do if d:IsA('BasePart')then t[#t+1]=d end end return t end
local function weldAll(m,root)for _,q in ipairs(parts(m))do q.Anchored=false q.CanCollide=false q.CanTouch=false q.CanQuery=false q.Massless=true if q~=root then local w=Instance.new('WeldConstraint',root)w.Part0=root w.Part1=q end end end
local function eye(m,x,y,z)ball(m,'Eye',Vector3.new(.24,.32,.18),Color3.fromRGB(20,20,25),CFrame.new(x,y,z))end
local function egg(name)local s=S[name]local c1=Color3.fromRGB(s[1],s[2],s[3])local c2=Color3.fromRGB(s[4],s[5],s[6])local ac=Color3.fromRGB(s[7],s[8],s[9])local k=s[10]local m=Instance.new('Model')m.Name=name local b=ball(m,'Body',Vector3.new(3.1,4.2,3.1),c1,CFrame.new())m.PrimaryPart=b ball(m,'Lower',Vector3.new(3.3,2.4,3.3),c2,CFrame.new(0,-.8,.05))ball(m,'Shine',Vector3.new(.5,.8,.2),ac,CFrame.new(-.65,.75,-1.48),Enum.Material.Neon)eye(m,-.48,.12,-1.55)eye(m,.48,.12,-1.55)mk(m,'Mouth',Vector3.new(.55,.12,.12),Color3.fromRGB(20,20,25),CFrame.new(0,-.4,-1.58))if k=='horn'then cyl(m,'Horn',Vector3.new(.42,1.4,.42),ac,CFrame.new(0,2.15,0)*CFrame.Angles(0,0,math.rad(90)),Enum.Material.Neon)elseif k=='ears'then for _,x in ipairs({-1,1})do local e=mk(m,'Ear',Vector3.new(.8,1.4,.45),c2,CFrame.new(x*1.05,1.65,0)*CFrame.Angles(0,0,math.rad(x*22)))e.Shape=Enum.PartType.Wedge end elseif k=='wings'then for _,x in ipairs({-1,1})do local q=mk(m,'Wing',Vector3.new(1.5,2.5,.35),c2,CFrame.new(x*1.95,.3,.25)*CFrame.Angles(0,0,math.rad(x*25)))q.Shape=Enum.PartType.Wedge end elseif k=='tentacles'then for i=1,4 do cyl(m,'Tentacle',Vector3.new(.42,1.7,.42),c2,CFrame.new((i-2.5)*.65,-2,-.1)*CFrame.Angles(0,0,math.rad(90)))end elseif k=='fangs'then for _,x in ipairs({-1,1})do local q=mk(m,'Fang',Vector3.new(.35,1,.3),ac,CFrame.new(x*.72,-.95,-1.52))q.Shape=Enum.PartType.Wedge end else for i=0,5 do local a=math.rad(i*60)local q=mk(m,'Spike',Vector3.new(.4,1,.4),ac,CFrame.new(math.cos(a)*1.8,.3,math.sin(a)*1.8))q.Shape=Enum.PartType.Wedge end end weldAll(m,b)return m end
local function star()local m=Instance.new('Model')m.Name='Star'local b=ball(m,'Center',Vector3.new(2.3,2.3,.8),Color3.fromRGB(255,207,42),CFrame.new(),Enum.Material.Neon)m.PrimaryPart=b for i=0,4 do local a=math.rad(-90+i*72)local q=mk(m,'Point',Vector3.new(1,2.2,.72),Color3.fromRGB(255,190,30),CFrame.new(math.cos(a)*1.85,math.sin(a)*1.85,0)*CFrame.Angles(0,0,a+math.rad(90)),nil,Enum.Material.Neon)q.Shape=Enum.PartType.Wedge end eye(m,-.42,.18,-.45)eye(m,.42,.18,-.45)mk(m,'Smile',Vector3.new(.65,.12,.12),Color3.fromRGB(35,28,20),CFrame.new(0,-.45,-.48))weldAll(m,b)return m end
local function badEggAncestor(o,stop)local x=o while x and x~=stop do if norm(x.Name):find('egg',1,true)then return true end x=x.Parent end return false end
local cache={}
local function findPet(name)if cache[name]and cache[name].Parent then return cache[name]end local want={}for _,a in ipairs(A[name]or{name})do want[norm(a)]=true end local best,bs=nil,-1 for ri,root in ipairs({RS,workspace})do local list=root:GetDescendants()for i,o in ipairs(list)do if i%1000==0 then task.wait()end if(o:IsA('Model')or o:IsA('Tool'))and not(P.Character and o:IsDescendantOf(P.Character))and not o:IsDescendantOf(Placed)then local n=norm(o.Name)local hit=want[n]if not hit then for _,k in ipairs({'PetName','DisplayName','ItemName','Title','Type'})do local v=o:GetAttribute(k)if v and want[norm(v)]then hit=true break end end end if hit and not badEggAncestor(o,root)then local sc=(ri==1 and 500 or 100)+(want[n]and 1000 or 0)+(o:IsA('Tool')and 200 or 150)if sc>bs then best,bs=o,sc end end end end end cache[name]=best return best end
local function clonePet(src,name)if not src then return nil end local ok,c=pcall(function()return src:Clone()end)if not ok then return nil end local kill={}for _,d in ipairs(c:GetDescendants())do if d:IsA('Script')or d:IsA('LocalScript')or d:IsA('ModuleScript')or d:IsA('Humanoid')or d:IsA('Animator')or d:IsA('ProximityPrompt')then kill[#kill+1]=d end end for _,d in ipairs(kill)do d:Destroy()end local m=c if c:IsA('Tool')then m=Instance.new('Model')for _,q in ipairs(c:GetChildren())do q.Parent=m end c:Destroy()end if not m:IsA('Model')or not m:FindFirstChildWhichIsA('BasePart',true)then if m then m:Destroy()end return nil end m.Name=name local ok2,sz=pcall(function()return m:GetExtentsSize()end)if ok2 then local mx=math.max(sz.X,sz.Y,sz.Z)if mx>.01 then pcall(function()m:ScaleTo(math.clamp(7/mx,.18,2.2))end)end end return m end
local function fallbackPet(name)local lum=name=='Luminous Cthulhu'local night=name=='Night Flame'local m=Instance.new('Model')m.Name=name local base=lum and Color3.fromRGB(170,55,225)or night and Color3.fromRGB(235,170,40)or Color3.fromRGB(130,85,190)local dark=lum and Color3.fromRGB(95,35,155)or night and Color3.fromRGB(90,65,28)or Color3.fromRGB(90,55,145)local b=ball(m,'Body',Vector3.new(4.8,3.8,5),base,CFrame.new())m.PrimaryPart=b ball(m,'Head',Vector3.new(3.5,3.1,3.5),base,CFrame.new(0,.8,-3))eye(m,-.6,.9,-4.65)eye(m,.6,.9,-4.65)if lum then for i=1,6 do cyl(m,'Tentacle',Vector3.new(.5,2.5,.5),Color3.fromRGB(230,90,250),CFrame.new((i-3.5)*.7,-2,-2.5)*CFrame.Angles(0,0,math.rad(90)),Enum.Material.Neon)end else for _,x in ipairs({-1.5,1.5})do for _,z in ipairs({-1,1.4})do cyl(m,'Leg',Vector3.new(.6,1.9,.6),dark,CFrame.new(x,-2,z)*CFrame.Angles(0,0,math.rad(90)))end end end for _,x in ipairs({-1,1})do local q=mk(m,'Wing',Vector3.new(1.7,3,.4),dark,CFrame.new(x*3,.5,.2)*CFrame.Angles(0,0,math.rad(x*25)))q.Shape=Enum.PartType.Wedge end weldAll(m,b)return m end
local function pet(name)local m=clonePet(findPet(name),name)if m then return m,true end return fallbackPet(name),false end
local function attach(tool,m,off)m.Parent=tool m:PivotTo(tool.Handle.CFrame*off)for _,q in ipairs(parts(m))do q.Anchored=false q.CanCollide=false q.CanTouch=false q.CanQuery=false q.Massless=true local w=Instance.new('WeldConstraint',tool.Handle)w.Part0=tool.Handle w.Part1=q end end
local function place(tool,m)local c=m:Clone()for _,d in ipairs(c:GetDescendants())do if d:IsA('WeldConstraint')or d:IsA('Motor6D')then d:Destroy()end end c.Parent=Placed for _,q in ipairs(parts(c))do q.Anchored=true q.CanCollide=false q.CanQuery=true end local mouse=P:GetMouse()local pos=mouse and mouse.Hit and mouse.Hit.Position local hrp=P.Character and P.Character:FindFirstChild('HumanoidRootPart')pos=pos or(hrp and(hrp.Position+hrp.CFrame.LookVector*7))or Vector3.zero local rp=RaycastParams.new()rp.FilterType=Enum.RaycastFilterType.Exclude rp.FilterDescendantsInstances={P.Character,Placed}local h=workspace:Raycast(pos+Vector3.new(0,30,0),Vector3.new(0,-80,0),rp)if h then pos=h.Position end c:PivotTo(CFrame.new(pos))local cf,sz=c:GetBoundingBox()c:PivotTo(c:GetPivot()+Vector3.new(0,pos.Y-(cf.Position.Y-sz.Y/2)+.05,0))tool:Destroy()end
local function tool(cat,name)local t=Instance.new('Tool')t.Name=name t.RequiresHandle=true t.CanBeDropped=false t:SetAttribute('SAE_V5_TOOL',true)t:SetAttribute('SAE_ID',Http:GenerateGUID(false))local h=mk(t,'Handle',Vector3.new(.35,.35,.35),Color3.new(),CFrame.new())h.Transparency=1 local m,real if cat=='Eggs'then m=egg(name)attach(t,m,CFrame.new(0,.28,-.72)*CFrame.Angles(0,math.rad(180),0))elseif cat=='Star'then m=star()attach(t,m,CFrame.new(0,.18,-.62)*CFrame.Angles(0,math.rad(180),0))else m,real=pet(name)attach(t,m,CFrame.new(0,.85,-2.15))t.Activated:Connect(function()place(t,m)end)end t.Parent=BP return real end
local function corner(o,r)local x=Instance.new('UICorner',o)x.CornerRadius=UDim.new(0,r or 8)end
local function stroke(o,a)local x=Instance.new('UIStroke',o)x.Color=C.border x.Transparency=a or .3 end
local function label(p,t,pos,size,z,col)local x=Instance.new('TextLabel',p)x.BackgroundTransparency=1 x.Position=pos x.Size=size x.Text=t x.TextColor3=col or C.w x.Font=Enum.Font.GothamMedium x.TextSize=z or 11 x.TextXAlignment=Enum.TextXAlignment.Left return x end
